20: /*
21:  * PVH variables.
22:  *
23:  * The variable xen_pvh needs to live in a data segment since it is used
24:  * after startup_{32|64} is invoked, which will clear the .bss segment.
25:  */
26: bool __ro_after_init xen_pvh;
27: EXPORT_SYMBOL_GPL(xen_pvh);
28: 
29: /*
30:  * Reserve e820 UNUSABLE regions to inflate the memory balloon.
31:  *
32:  * On PVH dom0 the host memory map is used, RAM regions available to dom0 are
33:  * located as the same place as in the native memory map, but since dom0 gets
34:  * less memory than the total amount of host RAM the ranges that can't be
35:  * populated are converted from RAM -> UNUSABLE.  Use such regions (up to the
36:  * ratio signaled in EXTRA_MEM_RATIO) in order to inflate the balloon driver at
37:  * boot.  Doing so prevents the guest (even if just temporary) from using holes
38:  * in the memory map in order to map grants or foreign addresses, and
39:  * hopefully limits the risk of a clash with a device MMIO region.  Ideally the
40:  * hypervisor should notify us which memory ranges are suitable for creating
41:  * foreign mappings, but that's not yet implemented.
42:  */
43: void __init xen_reserve_extra_memory(struct boot_params *bootp)
44: {
45: 	unsigned int i, ram_pages = 0, extra_pages;
46: 
47: 	for (i = 0; i < bootp->e820_entries; i++) {
48: 		struct boot_e820_entry *e = &bootp->e820_table[i];
49: 
50: 		if (e->type != E820_TYPE_RAM)
51: 			continue;
52: 		ram_pages += PFN_DOWN(e->addr + e->size) - PFN_UP(e->addr);
53: 	}
54: 
55: 	/* Max amount of extra memory. */
56: 	extra_pages = EXTRA_MEM_RATIO * ram_pages;
57: 
58: 	/*
59: 	 * Convert UNUSABLE ranges to RAM and reserve them for foreign mapping
60: 	 * purposes.
61: 	 */
62: 	for (i = 0; i < bootp->e820_entries && extra_pages; i++) {
63: 		struct boot_e820_entry *e = &bootp->e820_table[i];
64: 		unsigned long pages;
65: 
66: 		if (e->type != E820_TYPE_UNUSABLE)
67: 			continue;
68: 
69: 		pages = min(extra_pages,
70: 			PFN_DOWN(e->addr + e->size) - PFN_UP(e->addr));
71: 
72: 		if (pages != (PFN_DOWN(e->addr + e->size) - PFN_UP(e->addr))) {
73: 			struct boot_e820_entry *next;
74: 
75: 			if (bootp->e820_entries ==
76: 			    ARRAY_SIZE(bootp->e820_table))
77: 				/* No space left to split - skip region. */
78: 				continue;
79: 
80: 			/* Split entry. */
81: 			next = e + 1;
82: 			memmove(next, e,
83: 				(bootp->e820_entries - i) * sizeof(*e));
84: 			bootp->e820_entries++;
85: 			next->addr = PAGE_ALIGN(e->addr) + PFN_PHYS(pages);
86: 			e->size = next->addr - e->addr;
87: 			next->size -= e->size;
88: 		}
89: 		e->type = E820_TYPE_RAM;
90: 		extra_pages -= pages;
91: 
92: 		xen_add_extra_mem(PFN_UP(e->addr), pages);
93: 	}
94: }
