114: 		if (ret > 0)
115: 			xen_init_vga(&op.u.dom0_console,
116: 				     min(ret * sizeof(char),
117: 					 sizeof(op.u.dom0_console)),
118: 				     &boot_params->screen_info);
119: 	}
120: }
